arguments.command:
curl -s "https://slack.com/api/conversations.history?token=<TOKEN>&channel=C_Z1&limit=500" -o /tmp/slack_ideas.json && python3 -c "
import json
d=json.load(open('/tmp/slack_ideas.json'))
if not d.get('ok'):
    print('ERR', d)
else:
    for m in d['messages']:
        if m.get('ts') == m.get('thread_ts'):
            continue
        for r in m.get('reactions',[]):
            if r['name']=='rocket':
                print(m['ts'], r['name'], r['count'], '|', (m.get('text') or '')[:120])
"

